#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

int main() {
    int length;
    std::cin >> length;
    std::string inputStr;
    std::cin >> inputStr;

    int maxInnerLength = 0;
    int bracketsCount = 0;
    std::string outsideStr;
    std::string insideStr;

    for (int index = 0; index < length; index++) {
        if (inputStr[index] == '(') {
            outsideStr += "_";
            index++;
            while (index < length && inputStr[index] != ')') {
                insideStr += inputStr[index];
                index++;
            }
            insideStr += "_";
        } else {
            outsideStr += inputStr[index];
        }
    }

    std::vector<std::string> outsideParts;
    size_t start = 0, end;
    while ((end = outsideStr.find('_', start)) != std::string::npos) {
        outsideParts.push_back(outsideStr.substr(start, end - start));
        start = end + 1;
    }
    // Add the last part if any
    if (start < outsideStr.size()) {
        outsideParts.push_back(outsideStr.substr(start));
    }

    for (const auto& part : outsideParts) {
        maxInnerLength = std::max(maxInnerLength, static_cast<int>(part.length()));
    }

    std::vector<std::string> insideParts;
    start = 0;
    while ((end = insideStr.find('_', start)) != std::string::npos) {
        insideParts.push_back(insideStr.substr(start, end - start));
        start = end + 1;
    }
    // Add the last part if any
    if (start < insideStr.size()) {
        insideParts.push_back(insideStr.substr(start));
    }

    for (const auto& part : insideParts) {
        if (!part.empty()) {
            bracketsCount++;
        }
    }

    std::cout << maxInnerLength << " " << bracketsCount << std::endl;

    return 0;
}
